DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC2_GUIDE_THETRIUMPHALIMPERIUM' OR Tag GLOB 'TXT_KEY_CWC2_GUIDE_THETRIUMPHALIMPERIUM_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETRIUMPHALIMPERIUM_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETRIUMPHALIMPERIUM_CIV_TEXT_1','The Triumphal Imperium[NEWLINE]Victory-fed military strength and mobilisation that fade during quiet campaigns[NEWLINE]Domination[NEWLINE][NEWLINE]Prepare a sustainable army, then chain major-civilization combat victories. Momentum starts at 0, caps at 6 and grants +2% military Strength and +4% military Production per point. A complete owner-turn cycle without a qualifying victory loses 1. Defensive victories between your turns also count.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETRIUMPHALIMPERIUM_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETRIUMPHALIMPERIUM_CIV_TEXT_2','Secure Food, Production, Iron and normal research. Build or acquire a Hall of Triumphs for Barracks experience and +1 Culture. The civilization has no unearned empire Momentum bonus: choose the first war for achievable kills rather than expecting the laurel to win it.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETRIUMPHALIMPERIUM_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETRIUMPHALIMPERIUM_CIV_TEXT_3','Support Unbroken with ranged units and replacements. They retain the active Swordsman balance and gain a permanent +10% attacking bonus. At 4 Momentum original Unbroken gain +1 Movement and Hall cities gain +10% military Production. A major conquest gives +2 Momentum once per city site and a Hall after Bronze Working.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETRIUMPHALIMPERIUM_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETRIUMPHALIMPERIUM_CIV_TEXT_4','Use high Momentum to replace losses and exploit decisive openings. At 6 the empire has +12% military Strength and +24% military Production; a Hall adds 10 percentage points locally. Upgrade experienced Unbroken to preserve their attack promotion, while accounting for the loss of their original-type temporary movement.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETRIUMPHALIMPERIUM_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETRIUMPHALIMPERIUM_CIV_TEXT_5','- Offensive, defensive, ranged, naval and air combat kills against major military units can sustain Momentum.[NEWLINE]- Earned strength and native military Production reinforce successive successful campaigns.[NEWLINE]- Captured cities receive the actual Hall once Bronze Working is known, including puppets.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETRIUMPHALIMPERIUM_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETRIUMPHALIMPERIUM_CIV_TEXT_6','- The economy, strategic resources, Happiness and technology obey normal rules.[NEWLINE]- Quiet or unsuccessful cycles decay Momentum and can switch both threshold abilities off.[NEWLINE]- Barbarian, City-State and civilian deaths cannot build the engine.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETRIUMPHALIMPERIUM_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETRIUMPHALIMPERIUM_CIV_TEXT_7','- Protect exposed units and withdraw damaged armies to deny easy combat kills.[NEWLINE]- Force pauses, threaten supply routes and exploit the loss of March below 4 Momentum.[NEWLINE]- Use terrain and coordinated fire; the earned strength cap is only +12%, not permanent growth.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETRIUMPHALIMPERIUM_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETRIUMPHALIMPERIUM_CIV_TEXT_8','- Starting a war before assembling the units and resources to earn the first victories.[NEWLINE]- Treating the temporary extra Movement as an immediate movement refill.[NEWLINE]- Expecting repeated recaptures of one city to grant unlimited conquest Momentum.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETRIUMPHALIMPERIUM_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETRIUMPHALIMPERIUM_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Conical Union: An exposed network of secondary cities can offer distinct conquest targets; secured connections still support a normal defense.[NEWLINE][NEWLINE]The Lantern Fleet: Capturing accessible coastal cities can establish new training centers, but naval defenders can deny safe landings.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Laureate Commonwealth: A prepared defender that finishes wounded units can trade efficiently and deny a sustained imperial offensive.[NEWLINE][NEWLINE]The Threshold Court: Paid doorway reinforcement can make isolated city targets less vulnerable than they first appear.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETRIUMPHALIMPERIUM_CIV_HEADING_10','Implementation and timing limits');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETRIUMPHALIMPERIUM_CIV_TEXT_10','Each captured city site grants conquest Momentum once per Imperium player; recaptures still refresh victory activity and Hall eligibility. Movement activation does not refill moves. Owner-start decay uses the native PlayerDoTurn boundary, after the preceding cycle production settles. Source/database and Lua-mock checks are separate from native in-game acceptance.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETRIUMPHALIMPERIUM_DESCRIPTION','The Triumphal Imperium');
