INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETRIUMPHALIMPERIUM_BACKGROUND','Prepare a sustainable army, then chain major-civilization combat victories. Momentum starts at 0, caps at 6 and grants +2% military Strength and +4% military Production per point. A complete owner-turn cycle without a qualifying victory loses 1. Defensive victories between your turns also count.');
