INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETRIUMPHALIMPERIUM_STRATEGY','Prepare a sustainable army, then chain major-civilization combat victories. Momentum starts at 0, caps at 6 and grants +2% military Strength and +4% military Production per point. A complete owner-turn cycle without a qualifying victory loses 1. Defensive victories between your turns also count.[NEWLINE][NEWLINE]Secure Food, Production, Iron and normal research. Build or acquire a Hall of Triumphs for Barracks experience and +1 Culture. The civilization has no unearned empire Momentum bonus: choose the first war for achievable kills rather than expecting the laurel to win it.[NEWLINE][NEWLINE]Support Unbroken with ranged units and replacements. They retain the active Swordsman balance and gain a permanent +10% attacking bonus. At 4 Momentum original Unbroken gain +1 Movement and Hall cities gain +10% military Production. A major conquest gives +2 Momentum once per city site and a Hall after Bronze Working.[NEWLINE][NEWLINE]Use high Momentum to replace losses and exploit decisive openings. At 6 the empire has +12% military Strength and +24% military Production; a Hall adds 10 percentage points locally. Upgrade experienced Unbroken to preserve their attack promotion, while accounting for the loss of their original-type temporary movement.');
