INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETRIUMPHALIMPERIUM_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETRIUMPHALIMPERIUM_LEADER_TEXT_2','Secure Food, Production, Iron and normal research. Build or acquire a Hall of Triumphs for Barracks experience and +1 Culture. The civilization has no unearned empire Momentum bonus: choose the first war for achievable kills rather than expecting the laurel to win it.[NEWLINE][NEWLINE]Support Unbroken with ranged units and replacements. They retain the active Swordsman balance and gain a permanent +10% attacking bonus. At 4 Momentum original Unbroken gain +1 Movement and Hall cities gain +10% military Production. A major conquest gives +2 Momentum once per city site and a Hall after Bronze Working.[NEWLINE][NEWLINE]Use high Momentum to replace losses and exploit decisive openings. At 6 the empire has +12% military Strength and +24% military Production; a Hall adds 10 percentage points locally. Upgrade experienced Unbroken to preserve their attack promotion, while accounting for the loss of their original-type temporary movement.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETRIUMPHALIMPERIUM_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETRIUMPHALIMPERIUM_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Conical Union: An exposed network of secondary cities can offer distinct conquest targets; secured connections still support a normal defense.[NEWLINE][NEWLINE]The Lantern Fleet: Capturing accessible coastal cities can establish new training centers, but naval defenders can deny safe landings.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Laureate Commonwealth: A prepared defender that finishes wounded units can trade efficiently and deny a sustained imperial offensive.[NEWLINE][NEWLINE]The Threshold Court: Paid doorway reinforcement can make isolated city targets less vulnerable than they first appear.');
